@pytest.mark.parametrize("username,expected_status", [
    ("user1", 200),  # Valid username
    ("invalid_user", 404),  # User not found
    ("", 400)  # Invalid username supplied
])
def test_get_user_by_username(api_client, username, expected_status, valid_api_key):
    """
    Test GET /user/{username} for different response scenarios.
    """
    # Construct endpoint
    endpoint = f"user/{username}"
    headers = {"Authorization": f"Bearer {valid_api_key}"}

    # Perform GET request
    response = api_client.get(endpoint, headers=headers)

    # Verify response status code
    assert response.status_code == expected_status

    # Additional validations for 200 response
    if expected_status == 200:
        json_response = response.json()
        # Validate against JSON schema
        validate(instance=json_response, schema=USER_RESPONSE_SCHEMA)
        # Check example data (optional step)
        assert json_response["username"] == "theUser"
    elif expected_status == 404:
        assert response.json().get("message", "").lower() == "user not found"
    elif expected_status == 400:
        assert response.json().get("message", "").lower() == "invalid username supplied"


